<?php require "config.php"; $r=$conexion->query("SELECT * FROM certificados ORDER BY id DESC"); ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Listado de certificados</title><style>body{font-family:Arial;background:#eee;padding:20px}.box{max-width:1500px;margin:auto;background:#fff;padding:24px;border-radius:12px;overflow:auto}table{width:100%;border-collapse:collapse;margin-top:20px;min-width:1100px}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left;font-size:14px}th{background:#f3ead4}button,a{padding:10px 13px;background:#9b741c;color:white;border:0;border-radius:6px;text-decoration:none;display:inline-block;cursor:pointer}.tools{margin:15px 0;display:flex;gap:10px;flex-wrap:wrap}input[type=text]{padding:10px;width:280px}.ok{background:#d9f2df;color:#17632a;padding:5px 8px;border-radius:5px}.pending{background:#fff0c2;color:#795800;padding:5px 8px;border-radius:5px}.sent{background:#d9eaff;color:#174d86;padding:5px 8px;border-radius:5px}.secondary{background:#555}</style></head><body><div class="box"><a href="index.php">← Menú</a><h2>Listado de participantes y certificados</h2><div class="tools"><input id="buscar" type="text" placeholder="Buscar nombre, C.I., correo o código"><button type="button" onclick="selTodos()">SELECCIONAR TODOS</button><button type="button" class="secondary" onclick="selPendientes()">SELECCIONAR SIN CERTIFICADO</button></div>
<form method="post" action="generar_masivo.php"><table id="tabla"><tr><th></th><th>Nombre</th><th>C.I.</th><th>Correo electrónico</th><th>Programa</th><th>Fecha</th><th>Código</th><th>Certificado generado</th><th>Correo</th><th>Acciones</th></tr>
<?php while($c=$r->fetch_assoc()): $existe=!empty($c["archivo"]) && is_file(__DIR__."/certificados/".$c["archivo"]); $enviado=!empty($c["fecha_envio"]); ?>
<tr data-generado="<?=$existe?'1':'0'?>"><td><input type="checkbox" name="ids[]" value="<?=$c['id']?>"></td><td><?=htmlspecialchars($c["nombre"]." ".$c["apellido"])?></td><td><?=htmlspecialchars($c["ci"]??"")?></td><td><?=htmlspecialchars($c["correo"]??"")?></td><td><?=htmlspecialchars($c["programa"])?></td><td><?=htmlspecialchars($c["fecha_emision"])?></td><td><?=htmlspecialchars($c["codigo"])?></td><td><?=$existe?'<span class="ok">GENERADO</span>':'<span class="pending">PENDIENTE</span>'?></td><td><?=$enviado?'<span class="sent">ENVIADO</span>':'<span class="pending">NO ENVIADO</span>'?></td><td><?php if($existe):?><a href="certificados/<?=rawurlencode($c['archivo'])?>" download>Descargar</a> <a href="enviar_correo.php?id=<?=$c['id']?>">Enviar</a><?php else:?><a href="generar.php?id=<?=$c['id']?>">Generar</a><?php endif;?></td></tr>
<?php endwhile;?></table><br><button>GENERAR CERTIFICADOS SELECCIONADOS</button></form>
<form method="post" action="enviar_masivo.php" onsubmit="return confirm('¿Enviar por correo los certificados generados de las personas seleccionadas?');"><div class="tools"><button>📧 ENVIAR CERTIFICADOS SELECCIONADOS</button><span>Solo se enviarán registros con correo válido y certificado generado.</span></div><div id="idsEnviar"></div></form>
</div><script>function selTodos(){document.querySelectorAll('input[name="ids[]"]').forEach(x=>x.checked=true);sync()}function selPendientes(){document.querySelectorAll('#tabla tr[data-generado]').forEach(r=>{let x=r.querySelector('input[name="ids[]"]');if(x)x.checked=r.dataset.generado==='0'});sync()}function sync(){let d=document.getElementById('idsEnviar');d.innerHTML='';document.querySelectorAll('input[name="ids[]"]:checked').forEach(x=>{let h=document.createElement('input');h.type='hidden';h.name='ids[]';h.value=x.value;d.appendChild(h)})}document.querySelectorAll('input[name="ids[]"]').forEach(x=>x.addEventListener('change',sync));document.getElementById('buscar').addEventListener('input',function(){let q=this.value.toLowerCase();document.querySelectorAll('#tabla tr').forEach((r,i)=>{if(i===0)return;r.style.display=r.innerText.toLowerCase().includes(q)?'':'none'})});</script></body></html>